<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { Users, BookOpen, MapPin, Save, Send, ArrowLeft, Download, ClipboardPaste, Info, CheckCircle2, GraduationCap, LoaderCircle } from 'lucide-vue-next'
import PageHeading from '../components/PageHeading.vue'
import StatePanel from '../components/StatePanel.vue'
import StatCard from '../components/StatCard.vue'
import AppModal from '../components/AppModal.vue'
import AnalyticsChart from '../components/AnalyticsChart.vue'
import { toast } from '../components/ToastStack.vue'
import { api, allPages, query, encode, meetingText, type Section, type GradeSheet } from '../lib/api'
import { csvDownload } from '../lib/format'
import { parseGradePaste } from '../lib/grades'
import { useWorkspace } from '../stores/workspace'
import { useAsync } from '../lib/useAsync'

const route = useRoute(), router = useRouter(), workspace = useWorkspace(), { loading, error, run } = useAsync()
const sections = ref<Section[]>([]), section = ref<Section>(), sheet = ref<GradeSheet>(), edits = ref<Record<string, string>>({}), original = ref<Record<string, string>>({}), busy = ref(false), action = ref(''), paste = ref(''), actionError = ref(''), filter = ref('')
const isDetail = computed(() => typeof route.params.id === 'string' && !!route.params.id)
const published = computed(() => sheet.value?.gradeState === 'PUBLISHED')
const dirtyIds = computed(() => Object.keys(edits.value).filter(id => edits.value[id] !== original.value[id]))
const visibleRows = computed(() => sheet.value?.items.filter(row => `${row.studentId} ${row.studentName}`.toLowerCase().includes(filter.value.trim().toLowerCase())) || [])
const gradeValues = computed(() => Object.values(edits.value).filter(value => value !== '').map(Number))
const average = computed(() => gradeValues.value.length ? (gradeValues.value.reduce((a, b) => a + b, 0) / gradeValues.value.length).toFixed(1) : '—')
const distribution = computed(() => { const counts = [0, 0, 0, 0, 0]; for (const grade of gradeValues.value) counts[grade < 60 ? 0 : grade < 70 ? 1 : grade < 80 ? 2 : grade < 90 ? 3 : 4]!++; return counts })
const chartOption = computed(() => ({ grid: { top: 25, right: 22, bottom: 40, left: 40 }, tooltip: { trigger: 'axis' }, xAxis: { type: 'category', data: ['60分以下', '60—69', '70—79', '80—89', '90—100'], axisTick: { show: false }, axisLine: { lineStyle: { color: '#e3eadb' } }, axisLabel: { color: '#8c9d7c', fontSize: 10 } }, yAxis: { type: 'value', minInterval: 1, axisLabel: { color: '#a3af98', fontSize: 9 }, splitLine: { lineStyle: { color: '#f0f3e9' } } }, series: [{ type: 'bar', barMaxWidth: 40, data: distribution.value, itemStyle: { color: '#9ab681', borderRadius: [5, 5, 0, 0] }, label: { show: true, position: 'top', fontSize: 10, color: '#7a9364' } }] }))
function setSheet(value: GradeSheet) { sheet.value = value; edits.value = Object.fromEntries(value.items.map(row => [row.enrollmentId, row.grade == null ? '' : String(row.grade)])); original.value = { ...edits.value } }
async function load() { await run(async () => { if (isDetail.value) { const id = encode(String(route.params.id)); const result = await Promise.all([api<Section>('/sections/' + id), api<GradeSheet>('/teacher/sections/' + id + '/grades')]); section.value = result[0]; setSheet(result[1]) } else sections.value = await allPages<Section>('/teacher/sections' + query({ termId: workspace.termId })) }) }
watch([() => route.params.id, () => workspace.termId], load, { immediate: true })
async function save() { if (!sheet.value || !dirtyIds.value.length) return; busy.value = true; actionError.value = ''; try { const items = sheet.value.items.filter(row => dirtyIds.value.includes(row.enrollmentId)).map(row => { const value = edits.value[row.enrollmentId]!; if (value !== '' && (!/^\d{1,3}(\.\d{1,2})?$/.test(value) || Number(value) > 100)) throw new Error(`${row.studentName}的成绩须为0—100，最多两位小数。`); return { enrollmentId: row.enrollmentId, grade: value === '' ? null : Number(value), version: row.version } }); setSheet(await api<GradeSheet>('/teacher/sections/' + encode(sheet.value.sectionId) + '/grades', { method: 'PUT', body: { items } })); toast('成绩草稿已保存。正式发布前，学生看不到本次修改。') } catch (e) { actionError.value = e instanceof Error ? e.message : '成绩保存失败' } finally { busy.value = false } }
async function publish() { if (!sheet.value) return; busy.value = true; actionError.value = ''; try { setSheet(await api<GradeSheet>('/teacher/sections/' + encode(sheet.value.sectionId) + '/publish-grades', { method: 'POST', body: { version: sheet.value.version } })); action.value = ''; toast('成绩已正式发布，学生可以查看本次结果。') } catch (e) { actionError.value = e instanceof Error ? e.message : '发布失败' } finally { busy.value = false } }
function applyPaste() { try { const result = parseGradePaste(paste.value, new Set(sheet.value?.items.map(item => item.studentId) || [])); for (const row of sheet.value?.items || []) if (result.has(row.studentId)) edits.value[row.enrollmentId] = result.get(row.studentId) == null ? '' : String(result.get(row.studentId)); action.value = ''; paste.value = ''; toast(`已填入${result.size}行成绩，请检查并保存草稿。`) } catch (e) { actionError.value = e instanceof Error ? e.message : '填入失败' } }
function openAction(value: string) { actionError.value = ''; action.value = value }
function download() { if (sheet.value) csvDownload(`${section.value?.courseTitle || '班级'}-${sheet.value.sectionId}-成绩册.csv`, [['学号', '姓名', '草稿成绩', '上次发布成绩', '草稿版本'], ...sheet.value.items.map(row => [row.studentId, row.studentName, edits.value[row.enrollmentId], row.publishedGrade ?? '', row.version])]) }
</script>
<template><PageHeading eyebrow="TEACH WITH CARE, KEEP THINGS CLEAR" :title="isDetail ? section?.courseTitle || '班级成绩册' : '授课与成绩'" :description="isDetail ? `${section?.id || ''} · ${section?.termName || ''} · 认真记录每一份学习成果。` : '班级安排、学生名单与成绩发布，在一个工作台里清晰完成。'"><template v-if="isDetail"><button class="button button-secondary" @click="router.push('/teacher/sections')"><ArrowLeft :size="14"/>返回班级</button><button class="button button-secondary" :disabled="!sheet" @click="download"><Download :size="14"/>导出成绩册</button></template><select v-else v-model="workspace.termId" class="select-control" aria-label="选择学期"><option v-for="term in workspace.terms" :key="term.id" :value="term.id">{{ term.name }}</option></select></PageHeading><StatePanel v-if="loading" loading/><StatePanel v-else-if="error" :error="error" @retry="load"/><template v-else-if="!isDetail"><section class="stats-grid"><StatCard label="本学期授课班级" :value="sections.length" note="仅展示你的授课安排"><BookOpen/></StatCard><StatCard label="班级选课人数" :value="sections.reduce((sum, item) => sum + item.enrolledCount, 0)" note="各教学班实际选课记录"><Users/></StatCard><StatCard label="已发布成绩的班级" :value="sections.filter(item => item.gradeState === 'PUBLISHED').length" note="正式发布后学生可见"><CheckCircle2/></StatCard><StatCard label="待维护成绩的班级" :value="sections.filter(item => item.gradeState !== 'PUBLISHED').length" note="草稿与发布各有步骤" accent><GraduationCap/></StatCard></section><section class="card"><div class="card-header"><div><h2>我的授课班级</h2><p>{{ workspace.currentTerm?.name }} · 点击班级进入名单与成绩册</p></div></div><StatePanel v-if="!sections.length" title="当前学期暂无授课安排" description="教务分配的教学班会在这里显示。"/><div v-else class="table-wrap"><table><caption class="sr-only">授课班级</caption><thead><tr><th>课程 / 教学班</th><th>教学安排</th><th>选课人数</th><th>成绩状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in sections" :key="item.id"><td><strong>{{ item.courseTitle }}</strong><small>{{ item.id }} · {{ item.credits }} 学分</small></td><td><small v-for="(meeting, i) in item.meetings" :key="i"><MapPin :size="10"/> {{ meetingText(meeting) }}</small></td><td>{{ item.enrolledCount }} / {{ item.capacity }}</td><td><span class="tag" :class="{ 'tag-neutral': item.gradeState !== 'PUBLISHED' }">{{ item.gradeState === 'PUBLISHED' ? '已正式发布' : '草稿待发布' }}</span></td><td><RouterLink :to="'/teacher/sections/' + encode(item.id)" class="button button-secondary button-small">进入成绩册</RouterLink></td></tr></tbody></table></div></section></template><template v-else-if="sheet"><section class="stats-grid"><StatCard label="班级学生" :value="sheet.items.length" note="当前有效选课名单"><Users/></StatCard><StatCard label="已填成绩" :value="gradeValues.length" :note="`仍有${sheet.items.length - gradeValues.length}人未填`"><ClipboardPaste/></StatCard><StatCard label="当前成绩均分" :value="average" note="基于当前成绩册；含未保存编辑"><GraduationCap/></StatCard><StatCard label="成绩状态" :value="published ? '已发布' : '草稿'" :note="published ? '正式成绩已冻结；更正须由教务重开' : '草稿保存后仍需正式发布'" accent><CheckCircle2/></StatCard></section><div class="notice-banner"><Info :size="16"/><span>{{ published ? '本班成绩已正式发布。为保留清晰的更正记录，修改需要教务填写原因并重新开放成绩册。' : '成绩先保存为草稿，确认全班录入完整后再正式发布。发布使用班级版本校验，避免覆盖他人的更新。' }}</span></div><div v-if="actionError && !action" class="error-inline" role="alert">{{ actionError }}<button class="text-button" style="margin-left:12px" @click="load">重新读取最新成绩册</button></div><section class="card"><div class="card-header"><div><h2>班级名单与成绩</h2><p>版本 {{ sheet.version }} · {{ dirtyIds.length ? `${dirtyIds.length} 行尚未保存` : '已与服务端同步' }}</p></div><div class="heading-actions"><button class="button button-secondary button-small" :disabled="busy || published" @click="openAction('paste')"><ClipboardPaste :size="13"/>批量填入</button><button class="button button-secondary button-small" :disabled="busy || published || !dirtyIds.length" @click="save"><Save :size="13"/>保存草稿</button><button class="button button-small" :disabled="busy || published || !!dirtyIds.length || !sheet.items.length || gradeValues.length !== sheet.items.length" @click="openAction('publish')"><Send :size="13"/>正式发布</button></div></div><div class="filter-bar"><label class="search-field"><Users :size="14"/><input v-model="filter" placeholder="筛选学号或姓名" aria-label="筛选班级学生"></label><span class="muted" style="font-size:10px">共 {{ sheet.items.length }} 人 · 成绩范围0—100，最多两位小数</span></div><StatePanel v-if="!visibleRows.length" :title="sheet.items.length ? '没有匹配的学生' : '还没有学生选入这个班级'"/><div v-else class="table-wrap"><table><caption class="sr-only">班级成绩编辑表</caption><thead><tr><th>学号</th><th>学生姓名</th><th>当前成绩</th><th>上次正式成绩</th><th>编辑状态</th></tr></thead><tbody><tr v-for="row in visibleRows" :key="row.enrollmentId"><td class="mono">{{ row.studentId }}</td><td><strong>{{ row.studentName }}</strong></td><td><label :for="'grade-' + row.enrollmentId" class="sr-only">{{ row.studentName }}的成绩</label><input :id="'grade-' + row.enrollmentId" v-model="edits[row.enrollmentId]" class="grade-input" type="number" min="0" max="100" step="0.01" placeholder="未填" :disabled="published || busy"></td><td>{{ row.publishedGrade == null ? '尚未发布' : Number(row.publishedGrade).toFixed(1) }}</td><td><span class="tag" :class="dirtyIds.includes(row.enrollmentId) ? 'tag-gold' : 'tag-neutral'">{{ dirtyIds.includes(row.enrollmentId) ? '待保存' : published ? '已发布' : '已同步' }}</span></td></tr></tbody></table></div><div class="card-footer"><span>{{ published ? '正式发布成绩已经冻结。' : '批量保存中的任意一行校验失败时，本次保存不会提交任何一行。' }}</span><span>版本 {{ sheet.version }}</span></div></section><section class="card mt-24"><div class="card-header"><div><h2>当前成绩分布</h2><p>{{ published ? '正式成绩' : '当前成绩册草稿（包括未保存编辑）' }} · 未填成绩不计入</p></div></div><div class="chart-body"><AnalyticsChart :option="chartOption" :label="`成绩分布：60分以下${distribution[0]}人，60到69分${distribution[1]}人，70到79分${distribution[2]}人，80到89分${distribution[3]}人，90到100分${distribution[4]}人`"/></div></section></template><AppModal :open="!!action" :title="action === 'paste' ? '批量填入成绩' : '正式发布全班成绩'" :busy="busy" @close="action = ''"><div v-if="actionError" class="error-inline" role="alert">{{ actionError }}</div><template v-if="action === 'paste'"><p class="modal-description">每行填写“学号,成绩”，也支持从表格复制的制表符分隔内容。空成绩表示清空草稿；仅更新当前班级已存在的学生。</p><label class="field">粘贴成绩<textarea v-model="paste" style="min-height:210px;font-family:Consolas,monospace" placeholder="学号,成绩&#10;S1001,86.5&#10;S1002,92" spellcheck="false"/></label><p class="muted mt-12" style="font-size:10px">填入只修改当前编辑区；检查无误后仍需点击“保存草稿”。</p></template><template v-else><p class="modal-description">即将正式发布 {{ section?.courseTitle }}（{{ sheet?.sectionId }}）的全班成绩。</p><div class="preview-alert">发布后学生能够查看成绩，通过学分与先修资格按新结果更新。成绩将冻结，后续更正需要教务说明原因并重开成绩册。</div></template><template #footer><button class="button button-secondary" :disabled="busy" @click="action = ''">取消</button><button class="button" :disabled="busy" @click="action === 'paste' ? applyPaste() : publish()"><LoaderCircle v-if="busy" :size="14" class="spin"/>{{ busy ? '正在处理…' : action === 'paste' ? '检查并填入' : '确认正式发布' }}</button></template></AppModal></template>
